    #[test]
    fn exactly_six_reducer_owning_selects() {
        let source = include_str!("collector.rs");
        let reducer_owning_selects = source
            .lines()
            .filter(|line| {
                let line = line.trim();
                line.starts_with("command = receive_operator_command(") && line.ends_with(") => {")
            })
            .count();
        assert_eq!(
            reducer_owning_selects, 6,
            "receive_operator_command must remain wired into exactly six production select arms"
        );
    }

    #[test]
    fn watchdog_backoff_uses_exponential_delays_with_a_hard_cap() {
        let expected = [
            1_000, 2_000, 4_000, 8_000, 16_000, 32_000, 60_000, 60_000, 60_000,
        ];
        for (consecutive_failures, expected_ms) in expected.into_iter().enumerate() {
            assert_eq!(
                backoff_delay_ms(u32::try_from(consecutive_failures).unwrap()),
                expected_ms
            );
        }
        assert_eq!(backoff_delay_ms(u32::MAX), 60_000);
    }

    #[test]
    fn watchdog_silence_deadline_uses_monotonic_time() {
        let policy = LivenessPolicy { timeout_ms: 30_000 };
        let last_event_at = Instant::now();

        assert_eq!(
            silence_deadline(last_event_at, &policy).duration_since(last_event_at),
            Duration::from_secs(30)
        );
    }

    #[test]
    fn watchdog_backoff_resets_after_the_first_reconnected_event() {
        let mut backoff = ReconnectBackoff::default();

        assert_eq!(backoff.on_watchdog_silence(), 1_000);
        assert_eq!(backoff.consecutive_failures, 1);
        assert_eq!(backoff.on_watchdog_silence(), 2_000);
        assert_eq!(backoff.consecutive_failures, 2);

        backoff.on_event();
        assert_eq!(backoff.consecutive_failures, 0);
        assert_eq!(backoff.on_watchdog_silence(), 1_000);
        assert_eq!(backoff.consecutive_failures, 1);
    }

    #[test]
    fn provider_stop_interrupts_codex_discovery() {
        const TARGET_NAME: &str =
            "rollout-2026-08-27T00-00-00-00000000-0000-4000-8000-000000000000.jsonl";

        let directory = tempfile::tempdir().unwrap();
        let root = directory.path().join("home/.codex/sessions");
        std::fs::create_dir_all(&root).unwrap();
        let target = root.join(TARGET_NAME);
        let targets = TargetSet::new([ProviderTarget {
            provider: Provider::Codex,
            path: target.clone(),
        }]);
        let diagnostics = crate::provider::ProviderDiagnostics::default();
        let mut worker = AdapterProviderWorker::new(
            vec![DiscoveryRoot {
                provider: Provider::Codex,
                path: root.clone(),
            }],
            diagnostics.clone(),
        );
        let mut pending = PendingEvents::new(diagnostics.clone());
        let mut watch_requests = Vec::new();
        let mut cycle =
            crate::provider::test_provider_cycle(&targets, &mut pending, &mut watch_requests);
        worker.process(&mut cycle).unwrap();
        let (sender, mut receiver) = mpsc::channel(16);
        pending.flush_to(&sender);
        while receiver.try_recv().is_ok() {}

        std::fs::write(&target, b"").unwrap();
        for index in 1..32 {
            let name = format!(
                "rollout-2026-08-27T00-00-{index:02}-00000000-0000-4000-8000-{index:012}.jsonl"
            );
            std::fs::write(root.join(name), b"").unwrap();
        }
        let stop_flag = Arc::new(AtomicBool::new(false));
        let hook_stop = Arc::clone(&stop_flag);
        crate::provider::set_discovery_file_type_hook(move |_| {
            hook_stop.store(true, Ordering::Release);
            Ok(())
        });
        let mut watch_requests = Vec::new();
        let mut cycle = crate::provider::test_provider_cycle_with_stop(
            &targets,
            &mut pending,
            &stop_flag,
            &mut watch_requests,
        );

        worker.process(&mut cycle).unwrap();

        assert!(stop_flag.load(Ordering::Acquire));
        assert!(
            worker
                .roots
                .get(&(Provider::Codex, root))
                .unwrap()
                .discovery
                .files()
                .is_empty(),
            "shutdown waited for and published the discovery inventory"
        );
        assert_eq!(
            diagnostics.admission_open_attempts(),
            0,
            "shutdown allowed discovery to open an artifact"
        );
    }

    #[tokio::test]
