    fn named_reducer() -> (Reducer, SharedModel) {
        let topology = topology_from_snapshot(&snapshot_with_names()).unwrap();
        let (mut reducer, shared) = empty_reducer();
        reducer
            .reconcile_gap(ReconcileBatch {
                topology,
                gap_kind: GapKind::Startup,
            })
            .unwrap();
        (reducer, shared)
    }

