    #[test]
    fn flat_pane_agent_detected_is_invalidation_without_topology_mutation() {
        let shared = known_pane_model();
        let flat_diagnostics = PrimaryStreamDiagnosticsHandle::default();
        let flat = flat_pane_agent_detected("w1:p4", flat_diagnostics.clone());
        assert_eq!(
            classify_primary_event(&flat.event),
            PrimaryEventClass::TopologyHint
        );
        assert!(
            normalize_event(&shared, "flat-frame-session", &flat)
                .unwrap()
                .is_empty()
        );

        let nested_diagnostics = PrimaryStreamDiagnosticsHandle::default();
        let nested = nested_pane_agent_detected(nested_diagnostics.clone());
        assert_eq!(
            classify_primary_event(&nested.event),
            PrimaryEventClass::TopologyHint
        );
        assert!(shared.borrow().pane("w1:p4").is_some());
        assert_eq!(flat_diagnostics.snapshot().flat_pane_agent_detected, 1);
        assert_eq!(nested_diagnostics.snapshot().flat_pane_agent_detected, 0);
    }

    #[test]
    fn flat_pane_agent_detected_participates_in_resync_admission() {
        let diagnostics = PrimaryStreamDiagnosticsHandle::default();
        let flat_known = flat_pane_agent_detected("w1:p4", diagnostics.clone());
        let flat_unknown = flat_pane_agent_detected("w1:p9", diagnostics.clone());
        let nested = nested_pane_agent_detected(diagnostics);

        for received in [flat_known, flat_unknown, nested] {
            assert_eq!(
                classify_primary_event(&received.event),
                PrimaryEventClass::TopologyHint
            );
        }
    }

    fn status_event_received(event: &str, status: &str) -> ReceivedEvent {
        ReceivedEvent {
            event: event.to_owned(),
            data: json!({
                "pane_id": "w1:p1",
                "terminal_id": "terminal-1",
                "agent_status": status,
            }),
            primary_stream_diagnostics: PrimaryStreamDiagnosticsHandle::default(),
        }
    }

    fn status_received(status: &str) -> ReceivedEvent {
        status_event_received("pane_agent_status_changed", status)
    }

    fn pane_status_test_model(
        admitted: bool,
        execution_state: ExecState,
        pane_status: Option<PaneAgentStatus>,
    ) -> DomainModel {
        let run_id = RunId::new();
        let mut model = DomainModel::default();
        if admitted {
            model.insert_workspace(Workspace {
                workspace_id: "w1".to_owned(),
            });
            model.insert_tab(Tab {
                tab_id: "w1:t1".to_owned(),
                workspace_id: "w1".to_owned(),
                label: None,
            });
            model.insert_pane(Pane {
                pane_id: "w1:p1".to_owned(),
                workspace_id: "w1".to_owned(),
                tab_id: "w1:t1".to_owned(),
                terminal_id: "terminal-1".to_owned(),
                display_name: None,
            });
        }
        model.insert_task_run(TaskRun {
            run_id,
            key: RunKey::Controller("pane-status-run".to_owned()),
            display_ordinal: DisplayOrdinal::new(1),
            state: TaskState::Running,
            has_controller_task_state_event: false,
            created_at_ms: None,
            updated_at_ms: None,
            finished_at_ms: None,
            subject: None,
            dismissed_at_ms: None,
        });
        model.insert_execution(Execution {
            execution_id: "execution-1".to_owned(),
            pane_id: "w1:p1".to_owned(),
            terminal_id: "terminal-1".to_owned(),
            task_run_id: run_id,
            state: execution_state,
        });
        if let Some(status) = pane_status {
            model.set_pane_agent_status("w1:p1".to_owned(), status);
        }
        model
    }

    async fn apply_primary_pane_status_event_for_test(
        model: DomainModel,
        event: &str,
        status: &str,
    ) -> (Arc<DomainModel>, i64, bool) {
        let directory = tempfile::tempdir().unwrap();
        let root = crate::lockfile::StateRoot(directory.path().to_path_buf());
        let store = open_writer(&root).unwrap();
        let (lifecycle, writer) = spawn_writer(store).unwrap();
        let mut persistence =
            RuntimePersistence::new_for_test(writer, Arc::new(RecordingOccurrenceSink::default()))
                .0;
        let (mut reducer, shared) = Reducer::new(RestoredState {
            model,
            next_ordinal: 2,
            next_ingest_seq: Some(1),
            event_ledger: Vec::new(),
        });
        let (provider_sender, mut provider, provider_thread) = inactive_provider_integration();
        let (performance, _sampler) =
            performance_tracker(Arc::new(TestPerformanceClock::new(Duration::ZERO)));
        let mut owner = OwnerTracker {
            terminal_id: None,
            pane_id: None,
            started_at_ms: 1,
        };

        let produced = apply_received_event(
            &mut reducer,
            &shared,
            &mut persistence,
            &mut owner,
            "status-session",
            status_event_received(event, status),
            performance.admit(),
            &mut PendingTopologyClosures::default(),
            &mut provider,
        )
        .await
        .unwrap();
        let snapshot = Arc::clone(&shared.borrow());

        drop(provider_sender);
        provider_thread.stop().await.unwrap();
        drop(persistence);
        shutdown_writer(lifecycle).await;
        let connection = rusqlite::Connection::open(crate::store::database_path(&root)).unwrap();
        let ledger_count = connection
            .query_row("SELECT COUNT(*) FROM events", [], |row| {
                row.get::<_, i64>(0)
            })
            .unwrap();
        (snapshot, ledger_count, produced)
    }

    async fn apply_primary_pane_status_for_test(
        model: DomainModel,
        status: &str,
    ) -> (Arc<DomainModel>, i64, bool) {
        apply_primary_pane_status_event_for_test(model, "pane_agent_status_changed", status).await
    }

