    #[test]
    fn admitted_meta_sidecar_synthesizes_dispatch_and_started() {
        let directory = tempfile::tempdir().unwrap();
        let root = directory.path().join("home/.claude/projects");
        let session = "11111111-1111-4111-8111-111111111111";
        let target = root.join(format!("project/{session}.jsonl"));
        let subagents = root.join(format!("project/{session}/subagents"));
        let transcript = subagents.join("agent-child.jsonl");
        let meta = subagents.join("agent-child.meta.json");
        std::fs::create_dir_all(&subagents).unwrap();
        std::fs::write(
            &target,
            format!(
                "{{\"type\":\"assistant\",\"timestamp\":\"2026-08-24T00:00:00Z\",\"sessionId\":\"{session}\"}}\n"
            ),
        )
        .unwrap();
        std::fs::write(&transcript, "").unwrap();
        std::fs::write(
            &meta,
            format!(
                "{{\"agentType\":\"reviewer\",\"description\":\"Review lane synthesis\",\"agentId\":\"child\",\"sessionId\":\"{session}\"}}"
            ),
        )
        .unwrap();
        let diagnostics = crate::provider::ProviderDiagnostics::default();
        let mut worker = AdapterProviderWorker::new(
            vec![DiscoveryRoot {
                provider: Provider::Claude,
                path: root,
            }],
            diagnostics.clone(),
        );
        let targets = TargetSet::new([ProviderTarget {
            provider: Provider::Claude,
            path: target,
        }]);
        let mut pending = PendingEvents::new(diagnostics);

        process_adapter_worker(&mut worker, &targets, &mut pending);
        let synthesized = drain_pending(&mut pending)
            .into_iter()
            .filter_map(|event| match event {
                ProviderEvent::Synthesized(event) => Some(event),
                _ => None,
            })
            .filter(|event| {
                event
                    .metadata
                    .event_id
                    .starts_with("log:agent-child.meta.json:")
            })
            .collect::<Vec<_>>();

        assert_eq!(synthesized.len(), 2);
        assert!(matches!(
            synthesized[0].event,
            crate::model::ControllerEventKind::Dispatch { .. }
        ));
        assert!(matches!(
            synthesized[1].event,
            crate::model::ControllerEventKind::TaskStarted
        ));
        assert_eq!(
            synthesized[0].metadata.event_id,
            "log:agent-child.meta.json:0:dispatch:child"
        );
        assert_eq!(
            synthesized[1].metadata.event_id,
            "log:agent-child.meta.json:0:task-started:child"
        );
    }

    #[test]
    fn pane_root_basename_twins_open_only_single_newest_artifact() {
        let directory = tempfile::tempdir().unwrap();
        let root = directory.path().join("home/.claude/projects");
        let session = "11111111-1111-4111-8111-111111111111";
        let older = root.join(format!("project-a/{session}.jsonl"));
        let newer = root.join(format!("project-b/{session}.jsonl"));
        for path in [&older, &newer] {
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(
                path,
                format!(
                    "{{\"type\":\"assistant\",\"uuid\":\"record-{session}\",\"timestamp\":\"2026-08-24T00:00:00Z\",\"sessionId\":\"{session}\",\"isSidechain\":false}}\n"
                ),
            )
            .unwrap();
        }
        let old_time = SystemTime::UNIX_EPOCH + Duration::from_secs(1_000);
        let new_time = SystemTime::UNIX_EPOCH + Duration::from_secs(2_000);
        std::fs::File::options()
            .write(true)
            .open(&older)
            .unwrap()
            .set_times(std::fs::FileTimes::new().set_modified(old_time))
            .unwrap();
        std::fs::File::options()
            .write(true)
            .open(&newer)
            .unwrap()
            .set_times(std::fs::FileTimes::new().set_modified(new_time))
            .unwrap();
        let diagnostics = crate::provider::ProviderDiagnostics::default();
        let mut worker = AdapterProviderWorker::new(
            vec![DiscoveryRoot {
                provider: Provider::Claude,
                path: root,
            }],
            diagnostics.clone(),
        );
        let targets = TargetSet::new([ProviderTarget {
            provider: Provider::Claude,
            path: older.clone(),
        }]);
        let mut pending = PendingEvents::new(diagnostics);

        process_adapter_worker(&mut worker, &targets, &mut pending);

        assert_eq!(tail_count_for_absolute(&worker, &older), 0);
        assert_eq!(tail_count_for_absolute(&worker, &newer), 1);
        assert_eq!(worker.tails.len(), 1);
    }

    #[test]
    fn wired_worker_record_ordinal_is_restart_stable_at_nonzero_offset() {
        use std::io::Write;

        let directory = tempfile::tempdir().unwrap();
        let rollout = "22222222-2222-4222-8222-222222222222";
        let root = directory.path().join("home/.codex/sessions");
        std::fs::create_dir_all(&root).unwrap();
        let path = root.join(format!("rollout-2026-08-24T00-00-00-{rollout}.jsonl"));
        std::fs::write(
            &path,
            format!(
                "{{\"timestamp\":\"2026-08-24T00:00:00Z\",\"type\":\"session_meta\",\"payload\":{{\"id\":\"{rollout}\",\"session_id\":\"{rollout}\",\"cwd\":\"/repo\",\"originator\":\"codex\",\"cli_version\":\"0.149.0\"}}}}\n{{\"timestamp\":\"2026-08-24T00:00:01Z\",\"type\":\"event_msg\",\"payload\":{{\"type\":\"task_started\"}}}}\n"
            ),
        )
        .unwrap();
        let diagnostics = crate::provider::ProviderDiagnostics::default();
        let mut worker = AdapterProviderWorker::new(
            vec![DiscoveryRoot {
                provider: Provider::Codex,
                path: root,
            }],
            diagnostics.clone(),
        );
        let targets = TargetSet::new([ProviderTarget {
            provider: Provider::Codex,
            path: path.clone(),
        }]);
        let mut pending = PendingEvents::new(diagnostics);
        process_adapter_worker(&mut worker, &targets, &mut pending);
        let _ = drain_pending(&mut pending);

        writeln!(
            std::fs::OpenOptions::new().append(true).open(&path).unwrap(),
            "{{\"timestamp\":\"2026-08-24T00:00:02Z\",\"type\":\"event_msg\",\"payload\":{{\"type\":\"turn_aborted\"}}}}"
        )
        .unwrap();
        process_adapter_worker(&mut worker, &targets, &mut pending);
        let events = drain_pending(&mut pending);

        assert!(events.iter().any(|event| matches!(
            event,
            ProviderEvent::Synthesized(controller)
                if controller.metadata.event_id == format!(
                    "log:{}:2:cancelled:{rollout}",
                    path.file_name().unwrap().to_string_lossy()
                )
        )));
    }

    const RESTART_BACKFILL_ROLLOUT: &str = "99999999-9999-4999-8999-999999999999";

    fn restart_backfill_log() -> String {
        format!(
            concat!(
                "{{\"timestamp\":\"2026-08-24T00:00:00Z\",\"type\":\"session_meta\",\"payload\":{{\"id\":\"{0}\",\"session_id\":\"{0}\",\"cwd\":\"/repo\",\"originator\":\"codex_cli_rs\",\"cli_version\":\"0.149.0\"}}}}\n",
                "{{\"timestamp\":\"2026-08-24T00:00:01Z\",\"type\":\"turn_context\",\"payload\":{{\"turn_id\":\"turn-1\",\"model\":\"gpt-5.6-sol\",\"effort\":\"xhigh\",\"sandbox_policy\":{{\"type\":\"workspace-write\"}}}}}}\n",
                "{{\"timestamp\":\"2026-08-24T00:00:02Z\",\"type\":\"event_msg\",\"payload\":{{\"type\":\"task_started\"}}}}\n",
                "{{\"timestamp\":\"2026-08-24T00:00:03Z\",\"type\":\"event_msg\",\"payload\":{{\"type\":\"token_count\",\"info\":{{\"last_token_usage\":{{\"output_tokens\":42}},\"model_context_window\":114000}}}}}}\n",
                "{{\"timestamp\":\"2026-08-24T00:00:04Z\",\"type\":\"event_msg\",\"payload\":{{\"type\":\"turn_aborted\"}}}}\n"
            ),
            RESTART_BACKFILL_ROLLOUT
        )
    }

    fn restart_backfill_worker(root: &Path) -> AdapterProviderWorker {
        AdapterProviderWorker::new_with_log_lane_config(
            vec![DiscoveryRoot {
                provider: Provider::Codex,
                path: root.to_path_buf(),
            }],
            crate::provider::ProviderDiagnostics::default(),
            LogLaneConfig {
                complete_grace_ms: 0,
                headless_inactivity_ms: i64::MAX / 2,
                ..LogLaneConfig::default()
            },
            None,
        )
    }

    async fn apply_restart_backfill_events(
        events: impl IntoIterator<Item = ProviderEvent>,
        reducer: &mut Reducer,
        shared: &SharedModel,
        persistence: &mut RuntimePersistence,
    ) {
        let coverage = SourceCoverageRegistry::new(SourceAvailability::Available);
        for event in events {
            apply_provider_event(
                event,
                "restart-backfill",
                reducer,
                shared,
                persistence,
                &coverage,
            )
            .await
            .unwrap();
        }
    }

    struct PersistedRestartBackfill {
        _directory: tempfile::TempDir,
        provider_root: PathBuf,
        targets: TargetSet,
        state_root: StateRoot,
        run_id: RunId,
        first_telemetry: crate::model::RunTelemetry,
        terminal_sources: HashMap<RunId, String>,
        restored: RestoredState,
    }

    async fn persist_restart_backfill() -> PersistedRestartBackfill {
        let directory = tempfile::tempdir().unwrap();
        let provider_root = directory.path().join("home/.codex/sessions");
        std::fs::create_dir_all(&provider_root).unwrap();
        let artifact = provider_root.join(format!(
            "rollout-2026-08-25T00-00-00-{RESTART_BACKFILL_ROLLOUT}.jsonl"
        ));
        let targets = TargetSet::new([ProviderTarget {
            provider: Provider::Codex,
            path: artifact.clone(),
        }]);
        let mut worker = restart_backfill_worker(&provider_root);
        let mut pending = PendingEvents::new(crate::provider::ProviderDiagnostics::default());
        process_adapter_worker(&mut worker, &TargetSet::default(), &mut pending);
        let _ = drain_pending(&mut pending);
        std::fs::write(&artifact, restart_backfill_log()).unwrap();
        process_adapter_worker(&mut worker, &targets, &mut pending);

        let state_path = directory.path().join("state");
        std::fs::create_dir_all(&state_path).unwrap();
        let state_root = StateRoot(state_path);
        let store = open_writer(&state_root).unwrap();
        let (lifecycle, writer) = spawn_writer(store).unwrap();
        let mut persistence = test_runtime(writer);
        let (mut reducer, shared) = Reducer::new(RestoredState {
            model: DomainModel::default(),
            next_ordinal: 1,
            next_ingest_seq: Some(1),
            event_ledger: Vec::new(),
        });
        apply_restart_backfill_events(
            drain_pending(&mut pending),
            &mut reducer,
            &shared,
            &mut persistence,
        )
        .await;
        let run_id = shared
            .borrow()
            .task_run_by_key(&RunKey::Native {
                provider: Provider::Codex,
                sid: RESTART_BACKFILL_ROLLOUT.to_owned(),
            })
            .expect("initial pass creates the rollout run")
            .run_id;
        let first_telemetry = shared
            .borrow()
            .telemetry(&run_id)
            .expect("initial pass reads telemetry")
            .clone();
        drop(persistence);
        lifecycle.shutdown().await.unwrap();

        let reader = open_reader(&state_root).unwrap();
        let terminal_sources = reader.terminal_event_sources().unwrap();
        let restored = reader.load_restored_state().unwrap();
        PersistedRestartBackfill {
            _directory: directory,
            provider_root,
            targets,
            state_root,
            run_id,
            first_telemetry,
            terminal_sources,
            restored,
        }
    }

    fn replay_restart_backfill(fixture: &PersistedRestartBackfill) -> Vec<ProviderEvent> {
        replay_restart_backfill_originated(fixture)
            .into_iter()
            .map(|(event, _, _)| event)
            .collect()
    }

    fn replay_restart_backfill_originated(
        fixture: &PersistedRestartBackfill,
    ) -> Vec<(
        ProviderEvent,
        crate::model::ObservationOrigin,
        Option<Arc<crate::store::PersistHistoryDrain>>,
    )> {
        let mut worker = restart_backfill_worker(&fixture.provider_root);
        let mut pending = PendingEvents::new(crate::provider::ProviderDiagnostics::default());
        process_adapter_worker(&mut worker, &fixture.targets, &mut pending);
        pending.originated_events_for_test()
    }

    #[tokio::test]
    async fn restart_backfills_in_window_telemetry() {
        let fixture = persist_restart_backfill().await;
        assert_eq!(fixture.first_telemetry.output_tokens, 42);
        assert!(
            fixture.restored.model.telemetry(&fixture.run_id).is_none(),
            "restart seed must prove telemetry is reconstructed rather than persisted"
        );
        let replay = replay_restart_backfill(&fixture);
        let store = open_writer(&fixture.state_root).unwrap();
        let (lifecycle, writer) = spawn_writer(store).unwrap();
        let mut persistence = test_runtime(writer);
        let (mut reducer, shared) = Reducer::new(fixture.restored);
        apply_restart_backfill_events(replay, &mut reducer, &shared, &mut persistence).await;

        let snapshot = shared.borrow();
        let telemetry = snapshot
            .telemetry(&fixture.run_id)
            .expect("startup replay must reconstruct in-window telemetry without an append");
        assert_eq!(telemetry.output_tokens, 42);
        assert_eq!(telemetry.model.as_deref(), Some("gpt-5.6-sol"));
        assert_eq!(telemetry.effort.as_deref(), Some("xhigh"));
        assert_eq!(telemetry.sandbox.as_deref(), Some("workspace-write"));
        assert_eq!(snapshot.run_kind(&fixture.run_id), Some("codex_cli_rs"));
        drop(snapshot);
        drop(persistence);
        lifecycle.shutdown().await.unwrap();
    }

    #[tokio::test]
    async fn restart_does_not_duplicate_events() {
        let fixture = persist_restart_backfill().await;
        let ledger_len = fixture.restored.event_ledger.len();
        let next_ingest_seq = fixture.restored.next_ingest_seq;
        let replay = replay_restart_backfill(&fixture);
        assert!(
            replay
                .iter()
                .any(|event| matches!(event, ProviderEvent::Telemetry { .. })),
            "test precondition requires the startup pass to replay file content"
        );
        let store = open_writer(&fixture.state_root).unwrap();
        let (lifecycle, writer) = spawn_writer(store).unwrap();
        let mut persistence = test_runtime(writer);
        let (mut reducer, shared) = Reducer::new(fixture.restored);
        apply_restart_backfill_events(replay, &mut reducer, &shared, &mut persistence).await;
        assert_eq!(
            shared
                .borrow()
                .telemetry(&fixture.run_id)
                .expect("telemetry proves replay reached the reducer")
                .output_tokens,
            42
        );
        drop(persistence);
        lifecycle.shutdown().await.unwrap();

        let replayed = open_reader(&fixture.state_root)
            .unwrap()
            .load_restored_state()
            .unwrap();
        assert_eq!(replayed.event_ledger.len(), ledger_len);
        assert_eq!(replayed.next_ingest_seq, next_ingest_seq);
        assert_eq!(replayed.model.task_runs().count(), 1);
    }

    #[tokio::test]
    async fn restart_does_not_flap_restored_native_cancelled_lifecycle() {
        let fixture = persist_restart_backfill().await;
        let expected_run = fixture
            .restored
            .model
            .task_run(&fixture.run_id)
            .unwrap()
            .clone();
        let expected_lifecycle = fixture
            .restored
            .model
            .task_run_v6_state(&fixture.run_id)
            .expect("explicit abort must persist native lifecycle state")
            .clone();
        assert_eq!(expected_run.state, TaskState::Running);
        assert_eq!(expected_run.finished_at_ms, None);
        assert_eq!(
            expected_lifecycle
                .native_session_end
                .as_ref()
                .map(|end| end.status),
            Some(NativeSessionEndStatus::Cancelled),
            "explicit abort must persist a resumable native cancellation"
        );
        let ledger_len = fixture.restored.event_ledger.len();
        let next_ingest_seq = fixture.restored.next_ingest_seq;
        let replay = replay_restart_backfill_originated(&fixture);
        assert_eq!(
            replay
                .iter()
                .filter(|(event, _, _)| matches!(
                    event,
                    ProviderEvent::Synthesized(controller)
                        if matches!(controller.event, ControllerEventKind::Cancelled)
                ))
                .count(),
            1,
            "startup replay must contain the retained Controller Cancelled"
        );
        let store = open_writer(&fixture.state_root).unwrap();
        let (lifecycle, writer) = spawn_writer(store).unwrap();
        let mut persistence = test_runtime(writer);
        let (mut reducer, shared) = Reducer::new(fixture.restored);
        reducer.restore_terminal_event_sources(fixture.terminal_sources);
        let coverage = SourceCoverageRegistry::new(SourceAvailability::Available);
        for (index, (event, origin, history_manifest)) in replay.into_iter().enumerate() {
            apply_provider_event_originated(
                event,
                origin,
                history_manifest,
                "restart-backfill",
                &mut reducer,
                &shared,
                &mut persistence,
                &coverage,
            )
            .await
            .unwrap();
            let snapshot = shared.borrow();
            assert_eq!(
                snapshot.task_run(&fixture.run_id),
                Some(&expected_run),
                "replay event {index} changed the restored core run"
            );
            assert_eq!(
                snapshot.task_run_v6_state(&fixture.run_id),
                Some(&expected_lifecycle),
                "replay event {index} changed the restored native lifecycle"
            );
        }
        drop(persistence);
        lifecycle.shutdown().await.unwrap();

        let replayed = open_reader(&fixture.state_root)
            .unwrap()
            .load_restored_state()
            .unwrap();
        assert_eq!(replayed.event_ledger.len(), ledger_len);
        assert_eq!(replayed.next_ingest_seq, next_ingest_seq);
        assert_eq!(
            replayed.model.task_run(&fixture.run_id),
            Some(&expected_run),
            "replay persisted a core-state flap"
        );
        assert_eq!(
            replayed.model.task_run_v6_state(&fixture.run_id),
            Some(&expected_lifecycle),
            "replay persisted a native-lifecycle flap"
        );
    }

    #[tokio::test]
    async fn historical_start_with_later_source_order_clears_native_end() {
        let fixture = persist_restart_backfill().await;
        let stored_watermark = fixture
            .restored
            .model
            .task_run_v6_state(&fixture.run_id)
            .and_then(|state| state.lifecycle_watermark.as_ref())
            .expect("explicit abort must persist a lifecycle watermark")
            .clone();
        assert_eq!(
            fixture
                .restored
                .model
                .task_run_v6_state(&fixture.run_id)
                .and_then(|state| state.native_session_end.as_ref())
                .map(|end| end.status),
            Some(NativeSessionEndStatus::Cancelled)
        );
        let (mut resume, origin, history_manifest) = replay_restart_backfill_originated(&fixture)
            .into_iter()
            .find_map(|(event, origin, history_manifest)| match event {
                ProviderEvent::Synthesized(controller)
                    if matches!(controller.event, ControllerEventKind::TaskStarted) =>
                {
                    Some((controller, origin, history_manifest))
                }
                _ => None,
            })
            .expect("startup replay must contain the historical TaskStarted");
        resume.metadata.timestamp_ms = stored_watermark.source_at_ms;
        resume.metadata.receipt_time_ms = stored_watermark.observed_at_ms;
        resume.metadata.event_id = format!("{}~resume", stored_watermark.source_order);
        let candidate = crate::model::NativeLifecycleWatermark {
            source_at_ms: resume.metadata.timestamp_ms,
            observed_at_ms: resume.metadata.receipt_time_ms,
            source_order: resume.metadata.event_id.clone(),
        };
        assert!(
            candidate > stored_watermark,
            "test precondition requires only the stable source order to advance"
        );

        let store = open_writer(&fixture.state_root).unwrap();
        let (lifecycle, writer) = spawn_writer(store).unwrap();
        let mut persistence = test_runtime(writer);
        let (mut reducer, shared) = Reducer::new(fixture.restored);
        apply_provider_event_originated(
            ProviderEvent::Synthesized(resume),
            origin,
            history_manifest,
            "restart-backfill",
            &mut reducer,
            &shared,
            &mut persistence,
            &SourceCoverageRegistry::new(SourceAvailability::Available),
        )
        .await
        .unwrap();
        drop(persistence);
        lifecycle.shutdown().await.unwrap();
        let persisted = open_reader(&fixture.state_root)
            .unwrap()
            .load_restored_state()
            .unwrap();
        assert_eq!(
            persisted
                .model
                .task_run_v6_state(&fixture.run_id)
                .and_then(|state| state.lifecycle_watermark.as_ref()),
            Some(&candidate)
        );
        assert!(
            persisted
                .model
                .task_run_v6_state(&fixture.run_id)
                .unwrap()
                .native_session_end
                .is_none(),
            "the strictly later historical start must clear the retained native end"
        );
    }

    #[tokio::test]
    async fn restart_historical_start_missing_from_ledger_does_not_reopen_cancelled_lifecycle() {
        let fixture = persist_restart_backfill().await;
        let expected_run = fixture
            .restored
            .model
            .task_run(&fixture.run_id)
            .expect("restart fixture must persist its core run")
            .clone();
        let expected_lifecycle = fixture
            .restored
            .model
            .task_run_v6_state(&fixture.run_id)
            .expect("restart fixture must persist its native lifecycle")
            .clone();
        assert_eq!(expected_run.state, TaskState::Running);
        assert_eq!(
            expected_lifecycle
                .native_session_end
                .as_ref()
                .map(|end| end.status),
            Some(NativeSessionEndStatus::Cancelled)
        );
        let replay = replay_restart_backfill_originated(&fixture);
        let started_event_id = replay
            .iter()
            .find_map(|(event, _, _)| match event {
                ProviderEvent::Synthesized(controller)
                    if matches!(controller.event, ControllerEventKind::TaskStarted) =>
                {
                    Some(controller.metadata.event_id.clone())
                }
                _ => None,
            })
            .expect("startup replay must contain the historical TaskStarted");
        let cancelled_event_id = replay
            .iter()
            .find_map(|(event, _, _)| match event {
                ProviderEvent::Synthesized(controller)
                    if matches!(controller.event, ControllerEventKind::Cancelled) =>
                {
                    Some(controller.metadata.event_id.clone())
                }
                _ => None,
            })
            .expect("startup replay must contain the retained Controller Cancelled");
        let connection =
            rusqlite::Connection::open(crate::store::database_path(&fixture.state_root)).unwrap();
        assert_eq!(
            connection
                .execute(
                    "DELETE FROM event_ledger WHERE event_id = ?1",
                    [&started_event_id],
                )
                .unwrap(),
            1,
            "fixture must prune only the historical TaskStarted ledger row"
        );
        assert_eq!(
            connection
                .query_row(
                    "SELECT COUNT(*) FROM events WHERE event_id IN (?1, ?2)",
                    (&started_event_id, &cancelled_event_id),
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            2,
            "both historical event rows must survive the ledger-only prune"
        );
        assert_eq!(
            connection
                .query_row(
                    "SELECT COUNT(*) FROM event_ledger WHERE event_id = ?1",
                    [&cancelled_event_id],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            1,
            "the retained Cancelled must remain a ledger duplicate"
        );
        drop(connection);

        let reader = open_reader(&fixture.state_root).unwrap();
        let terminal_sources = reader.terminal_event_sources().unwrap();
        let restored = reader.load_restored_state().unwrap();
        assert_eq!(
            restored.model.task_run(&fixture.run_id),
            Some(&expected_run)
        );
        assert_eq!(
            restored.model.task_run_v6_state(&fixture.run_id),
            Some(&expected_lifecycle),
            "restart seed must restore the persisted native cancellation"
        );
        assert!(
            !restored
                .event_ledger
                .iter()
                .any(|entry| entry.event_id == started_event_id),
            "restart ledger must expose the pruned historical TaskStarted"
        );
        drop(reader);
        let store = open_writer(&fixture.state_root).unwrap();
        let (lifecycle, writer) = spawn_writer(store).unwrap();
        let mut persistence = test_runtime(writer);
        let (mut reducer, shared) = Reducer::new(restored);
        reducer.restore_terminal_event_sources(terminal_sources);
        let coverage = SourceCoverageRegistry::new(SourceAvailability::Available);
        for (event, origin, history_manifest) in replay {
            apply_provider_event_originated(
                event,
                origin,
                history_manifest,
                "restart-backfill",
                &mut reducer,
                &shared,
                &mut persistence,
                &coverage,
            )
            .await
            .unwrap();
        }
        {
            let snapshot = shared.borrow();
            assert_eq!(
                snapshot.task_run(&fixture.run_id),
                Some(&expected_run),
                "historical TaskStarted replay changed the restored core run"
            );
            assert_eq!(
                snapshot.task_run_v6_state(&fixture.run_id),
                Some(&expected_lifecycle),
                "the later Cancelled lifecycle watermark did not prevent reopening"
            );
        }
        let persistence_status = persistence.snapshot.persistence;
        drop(persistence);
        lifecycle.shutdown().await.unwrap();

        let connection =
            rusqlite::Connection::open(crate::store::database_path(&fixture.state_root)).unwrap();
        let persisted_start_events = connection
            .query_row(
                "SELECT COUNT(*) FROM events WHERE event_id = ?1",
                [&started_event_id],
                |row| row.get::<_, i64>(0),
            )
            .unwrap();
        let persisted_start_ledger = connection
            .query_row(
                "SELECT COUNT(*) FROM event_ledger WHERE event_id = ?1",
                [&started_event_id],
                |row| row.get::<_, i64>(0),
            )
            .unwrap();
        drop(connection);
        let reader = open_reader(&fixture.state_root).unwrap();
        let persisted = reader.load_restored_state().unwrap();
        assert_eq!(
            persisted_start_events, 1,
            "historical TaskStarted replay persisted a duplicate Running event"
        );
        assert_eq!(
            persisted_start_ledger, 0,
            "historical TaskStarted replay repopulated its pruned ledger entry"
        );
        assert_eq!(
            persistence_status,
            crate::store::PersistenceStatus::Healthy,
            "historical TaskStarted replay attempted a conflicting durable event write"
        );
        assert_eq!(
            persisted.model.task_run(&fixture.run_id),
            Some(&expected_run),
            "historical TaskStarted replay persisted a core-state flap"
        );
        assert_eq!(
            persisted.model.task_run_v6_state(&fixture.run_id),
            Some(&expected_lifecycle),
            "historical TaskStarted replay persisted a lifecycle reopen"
        );
    }

    #[tokio::test]
    async fn event_ids_deterministic_across_replay() {
        let directory = tempfile::tempdir().unwrap();
        let root = StateRoot(directory.path().to_path_buf());
        let store = open_writer(&root).unwrap();
        let (lifecycle, writer) = spawn_writer(store).unwrap();
        let mut persistence = test_runtime(writer);
        let (mut reducer, shared) = Reducer::new(RestoredState {
            model: DomainModel::default(),
            next_ordinal: 1,
            next_ingest_seq: Some(1),
            event_ledger: Vec::new(),
        });
        let mut synthesis = crate::provider::lane::Synthesis::default();
        let events = synthesis.synthesize_batch(
            Path::new("session.jsonl"),
            [(
                7,
                crate::provider::facts::LogFact::Append {
                    scope: crate::provider::facts::SessionScope::ClaudeRoot(
                        "11111111-1111-4111-8111-111111111111".to_owned(),
                    ),
                    at_ms: 100,
                },
            )],
            &mut crate::provider::lane::Admission::new(0),
            &crate::provider::lane::AdmissionIndex::new(),
        );
        let event = events
            .into_iter()
            .find(|event| matches!(event, ProviderEvent::Synthesized(_)))
            .expect("append should synthesize task_started");
        for replay in [event.clone(), event.clone()] {
            apply_provider_event(
                replay,
                "session",
                &mut reducer,
                &shared,
                &mut persistence,
                &SourceCoverageRegistry::new(SourceAvailability::Available),
            )
            .await
            .unwrap();
        }

        assert_eq!(shared.borrow().task_runs().count(), 1);
        lifecycle.shutdown().await.unwrap();
        let restored = open_reader(&root).unwrap().load_restored_state().unwrap();
        assert_eq!(restored.event_ledger.len(), 1);
        assert_eq!(
            restored.event_ledger[0].event_id,
            "log:session.jsonl:7:task-started:11111111-1111-4111-8111-111111111111"
        );
        let next_ingest_seq = restored.next_ingest_seq;

        drop(persistence);
        let reopened_store = open_writer(&root).unwrap();
        let (reopened_lifecycle, reopened_writer) = spawn_writer(reopened_store).unwrap();
        let mut reopened_persistence = test_runtime(reopened_writer);
        let (mut reopened_reducer, reopened_shared) = Reducer::new(restored);
        for replay in [event.clone(), event] {
            apply_provider_event(
                replay,
                "session",
                &mut reopened_reducer,
                &reopened_shared,
                &mut reopened_persistence,
                &SourceCoverageRegistry::new(SourceAvailability::Available),
            )
            .await
            .unwrap();
        }
        assert_eq!(reopened_shared.borrow().task_runs().count(), 1);
        reopened_lifecycle.shutdown().await.unwrap();
        drop(reopened_persistence);
        let replayed = open_reader(&root).unwrap().load_restored_state().unwrap();
        assert_eq!(
            replayed.next_ingest_seq, next_ingest_seq,
            "hydrated durable ledger must suppress every post-restart replay apply"
        );
    }

    fn codex_records(owner: &str, agent: &str, event: &str) -> String {
        format!(
            "{{\"type\":\"session_meta\",\"payload\":{{\"id\":\"{owner}\",\"session_id\":\"{owner}\"}}}}\n{{\"type\":\"event_msg\",\"payload\":{{\"type\":\"sub_agent_activity\",\"event_id\":\"{event}\",\"occurred_at_ms\":1,\"agent_thread_id\":\"{agent}\",\"agent_path\":\"/root/{agent}\",\"kind\":\"interacted\"}}}}\n"
        )
    }

    fn append_codex_activity(path: &Path, agent: &str, event: &str) {
        use std::io::Write;

        writeln!(
            std::fs::OpenOptions::new()
                .append(true)
                .open(path)
                .unwrap(),
            "{{\"type\":\"event_msg\",\"payload\":{{\"type\":\"sub_agent_activity\",\"event_id\":\"{event}\",\"occurred_at_ms\":2,\"agent_thread_id\":\"{agent}\",\"agent_path\":\"/root/{agent}\",\"kind\":\"interacted\"}}}}"
        )
        .unwrap();
    }

    const G7_DETECTION_MS: i64 = 1_787_745_600_500;

    fn g7_provisional(
        terminal_id: &str,
        ordinal: i64,
        detected_at_ms: i64,
    ) -> (RunId, RunKey, TaskRun, Execution) {
        let run_id = RunId::new();
        let key = RunKey::Provisional {
            terminal_id: terminal_id.to_owned(),
            start_ms: detected_at_ms,
            seq: u64::try_from(ordinal).unwrap(),
        };
        (
            run_id,
            key.clone(),
            TaskRun {
                run_id,
                key,
                display_ordinal: DisplayOrdinal::new(ordinal),
                state: TaskState::Running,
                has_controller_task_state_event: false,
                created_at_ms: Some(detected_at_ms),
                updated_at_ms: Some(detected_at_ms),
                finished_at_ms: None,
                subject: None,
                dismissed_at_ms: None,
            },
            Execution {
                execution_id: format!("g7-execution-{terminal_id}"),
                pane_id: format!("g7-pane-{terminal_id}"),
                terminal_id: terminal_id.to_owned(),
                task_run_id: run_id,
                state: ExecState::Working,
            },
        )
    }

    fn g7_model(runs: &[(RunId, RunKey, TaskRun, Execution)]) -> DomainModel {
        let mut model = DomainModel::default();
        for (_, _, task_run, execution) in runs {
            model.insert_task_run(task_run.clone());
            model.insert_execution(execution.clone());
        }
        model
    }

    fn g7_execution_observation(
        run: &(RunId, RunKey, TaskRun, Execution),
        provider: Provider,
        native_session_id: Option<&str>,
        observed_at_ms: i64,
    ) -> NormalizedEvent {
        let mut metadata = metadata("session", "pane_agent_detected");
        metadata.timestamp_ms = observed_at_ms;
        metadata.receipt_time_ms = observed_at_ms;
        metadata.provider = Some(provider);
        metadata.native_session_id = native_session_id.map(str::to_owned);
        metadata.task_run_id = Some(run.0);
        NormalizedEvent::ExecutionBegin {
            metadata,
            execution: run.3.clone(),
        }
    }

    fn g7_targets(model: &DomainModel, runs: &[RunId]) -> TargetSet {
        let detections = runs
            .iter()
            .filter_map(|run_id| {
                let run = model.task_run(run_id)?;
                let RunKey::Provisional { start_ms, .. } = run.key else {
                    return None;
                };
                Some((*run_id, start_ms))
            })
            .collect();
        derive_provider_targets_with_codex_panes(model, &detections)
    }

    fn g7_worker(root: &Path) -> (AdapterProviderWorker, PendingEvents) {
        let diagnostics = crate::provider::ProviderDiagnostics::default();
        (
            AdapterProviderWorker::new(
                vec![DiscoveryRoot {
                    provider: Provider::Codex,
                    path: root.to_path_buf(),
                }],
                diagnostics.clone(),
            ),
            PendingEvents::new(diagnostics),
        )
    }

    fn g7_provider_integration() -> (
        mpsc::Sender<ProviderIngressEvent>,
        ProviderIntegration,
        ProviderThreadHandle,
    ) {
        let provider_diagnostics = crate::provider::ProviderDiagnostics::default();
        let (ignored_events, _ignored_receiver) = mpsc::channel(1);
        let provider_thread = spawn_provider_thread_with_diagnostics(
            AdapterProviderWorker::new(Vec::new(), provider_diagnostics.clone()),
            ignored_events,
            None,
            provider_diagnostics,
        )
        .unwrap();
        let (provider_sender, provider_events) = mpsc::channel(1);
        let initial_coverage = SourceCoverageRegistry::default();
        let (coverage_sender, _source_coverage) = watch::channel(initial_coverage);
        let (source_quality_sender, _source_quality) =
            watch::channel(ObservationQuality::Reconciling);
        let coverage = CoverageTracker::new(
            SourceAvailability::NotApplicable,
            coverage_sender,
            source_quality_sender,
        );
        let provider = ProviderIntegration::new(
            provider_events,
            provider_thread.target_publisher(),
            TargetSet::default(),
            coverage,
        );
        (provider_sender, provider, provider_thread)
    }

    fn g7_pane_event(event: &str, agent: &str, agent_session: Option<Value>) -> ReceivedEvent {
        let mut pane = json!({
            "agent": agent,
            "agent_status": "working",
            "pane_id": "g7-event-pane",
            "tab_id": "g7-event-tab",
            "terminal_id": "g7-event-terminal",
            "workspace_id": "g7-event-workspace"
        });
        if let Some(agent_session) = agent_session {
            pane["agent_session"] = agent_session;
        }
        ReceivedEvent {
            event: event.to_owned(),
            data: json!({ "pane": pane }),
            primary_stream_diagnostics: PrimaryStreamDiagnosticsHandle::default(),
        }
    }

    async fn g7_install_pane_snapshot(
        harness: &mut LaneModelHarness,
        provider: &mut ProviderIntegration,
        agent: &str,
        status: PaneAgentStatus,
        agent_session: Option<AgentSessionReference>,
    ) {
        let sessionless_codex_terminals = if agent == "codex" && agent_session.is_none() {
            HashSet::from(["g7-event-terminal".to_owned()])
        } else {
            HashSet::new()
        };
        let persist = harness
            .reducer
            .reconcile_snapshot(TopologySnapshot {
                workspaces: vec![Workspace {
                    workspace_id: "g7-event-workspace".to_owned(),
                }],
                tabs: vec![Tab {
                    tab_id: "g7-event-tab".to_owned(),
                    workspace_id: "g7-event-workspace".to_owned(),
                    label: None,
                }],
                panes: vec![PaneSnapshot {
                    pane_id: "g7-event-pane".to_owned(),
                    workspace_id: "g7-event-workspace".to_owned(),
                    tab_id: "g7-event-tab".to_owned(),
                    terminal_id: "g7-event-terminal".to_owned(),
                    display_name: None,
                    agent: Some(SnapshotAgent {
                        agent_name: agent.to_owned(),
                        status,
                    }),
                    agent_session,
                }],
            })
            .unwrap();
        let _ = persist_submission(&mut harness.persistence, &mut harness.reducer, persist)
            .await
            .unwrap();
        provider.observe_sessionless_codex_terminals(&harness.shared, &sessionless_codex_terminals);
        provider.publish_targets(&harness.shared);
        harness
            .persistence
            .refresh_snapshot(&harness.shared.borrow(), &provider.coverage.registry);
    }

    async fn g7_service_binding(
        harness: &mut LaneModelHarness,
        provider: &mut ProviderIntegration,
        binding: CodexPaneBinding,
    ) {
        service_provider_event(
            Some(ProviderIngressEvent {
                event: ProviderEvent::SourceState {
                    provider: Provider::Codex,
                    state: ProviderSourceState::AvailableWithBindings {
                        bindings: vec![binding],
                    },
                },
                admission: None,
                origin: crate::model::ObservationOrigin::Live,
                history_manifest: None,
            }),
            provider,
            "session",
            &mut harness.reducer,
            &harness.shared,
            &mut harness.persistence,
        )
        .await
        .unwrap();
    }

    fn g7_rollout(root: &Path, creation_ms: i64, label: &str) -> (PathBuf, String) {
        let (day, timestamp) = crate::provider::lane::local_rollout_fixture_parts(creation_ms);
        let day = root.join(day);
        std::fs::create_dir_all(&day).unwrap();
        let path = codex_artifact(&day, &format!("{timestamp}-{label}"));
        let rollout_id = codex_rollout_id(&path).expect("fixture filename carries a rollout UUID");
        std::fs::write(
            &path,
            format!(
                "{{\"timestamp\":\"2026-08-26T12:00:00Z\",\"type\":\"session_meta\",\"payload\":{{\"id\":\"{rollout_id}\",\"session_id\":\"{rollout_id}\",\"model\":\"gpt-rollout\",\"cwd\":\"/repo\",\"originator\":\"codex_cli_rs\"}}}}\n"
            ),
        )
        .unwrap();
        (path, rollout_id)
    }

    fn g7_binding_records(events: &[ProviderEvent]) -> Vec<CodexPaneBinding> {
        events
            .iter()
            .flat_map(|event| match event {
                ProviderEvent::SourceState {
                    state: ProviderSourceState::AvailableWithBindings { bindings },
                    ..
                } => bindings.clone(),
                _ => Vec::new(),
            })
            .collect()
    }

    fn g7_bindings(events: &[ProviderEvent]) -> Vec<(RunId, String)> {
        g7_binding_records(events)
            .into_iter()
            .map(|binding| (binding.run_id, binding.sid))
            .collect()
    }

    #[test]
    fn g7_round2_worker_binding_carries_detection_episode_timestamp() {
        let directory = tempfile::tempdir().unwrap();
        let root = directory.path().join("home/.codex/sessions");
        let (_, sid) = g7_rollout(&root, G7_DETECTION_MS + 500, "episode-timestamp");
        let run = g7_provisional("episode-timestamp", 1, G7_DETECTION_MS - 10_000);
        let model = g7_model(std::slice::from_ref(&run));
        let targets = derive_provider_targets_with_codex_panes(
            &model,
            &[(run.0, G7_DETECTION_MS)].into_iter().collect(),
        );
        let (mut worker, mut pending) = g7_worker(&root);

        process_adapter_worker(&mut worker, &targets, &mut pending);

        assert_eq!(
            g7_binding_records(&drain_pending(&mut pending)),
            vec![CodexPaneBinding {
                run_id: run.0,
                sid,
                observed_at_ms: G7_DETECTION_MS,
            }],
            "the queued binding must preserve the exact target detection episode"
        );
    }

    #[tokio::test]
    async fn g7_round3_ready_primary_precedes_and_preserves_ready_provider_event() {
        for attempt in 0..64 {
            let (performance, _sampler) =
                performance_tracker(Arc::new(SystemPerformanceClock::new()));
            let (primary_sender, mut primary_events) = admitted_channel(1, performance);
            let (provider_sender, provider_events) = mpsc::channel(1);
            let mut provider_events = Some(provider_events);
            let mut provider_event = None;

            primary_sender
                .send(g7_pane_event("pane_updated", "claude", None))
                .await
                .unwrap();
            provider_sender
                .send(ProviderIngressEvent {
                    event: ProviderEvent::SourceState {
                        provider: Provider::Codex,
                        state: ProviderSourceState::Available,
                    },
                    admission: None,
                    origin: crate::model::ObservationOrigin::Live,
                    history_manifest: None,
                })
                .await
                .unwrap();

            let first = receive_primary_or_provider(
                &mut primary_events,
                &mut provider_events,
                &mut provider_event,
                true,
            )
            .await;
            let PrimaryProviderReceipt::Primary(Some(primary)) = first else {
                panic!("ready provider event won attempt {attempt} before ready primary event");
            };
            let (primary, admission) = primary.into_parts();
            admission.complete();
            assert_eq!(primary.event, "pane_updated");
            assert!(
                provider_event.is_none(),
                "ready provider event must remain queued after primary wins"
            );

            let second = receive_primary_or_provider(
                &mut primary_events,
                &mut provider_events,
                &mut provider_event,
                true,
            )
            .await;
            assert!(matches!(second, PrimaryProviderReceipt::Provider));
            assert!(matches!(
                provider_event,
                Some(ProviderIngressEvent {
                    event: ProviderEvent::SourceState {
                        provider: Provider::Codex,
                        state: ProviderSourceState::Available,
                    },
                    admission: None,
                    ..
                })
            ));
        }
    }

    #[tokio::test]
    async fn g7_round2_explicit_path_event_clears_sessionless_detection() {
        let mut harness = LaneModelHarness::new();
        let (provider_sender, mut provider, provider_thread) = g7_provider_integration();
        g7_install_pane_snapshot(
            &mut harness,
            &mut provider,
            "codex",
            PaneAgentStatus::Working,
            None,
        )
        .await;
        let target = provider
            .published_targets
            .codex_panes()
            .next()
            .expect("sessionless Codex pane must publish before explicit path arrives");
        let provisional_key = harness
            .shared
            .borrow()
            .task_run(&target.run_id)
            .expect("published pane target must own a task run")
            .key
            .clone();
        let stale_sid = "55555555-5555-4555-8555-555555555555";
        let queued = CodexPaneBinding {
            run_id: target.run_id,
            sid: stale_sid.to_owned(),
            observed_at_ms: target.detected_at_ms,
        };

        g7_install_pane_snapshot(
            &mut harness,
            &mut provider,
            "codex",
            PaneAgentStatus::Working,
            Some(AgentSessionReference {
                source: "herdr".to_owned(),
                agent: "codex".to_owned(),
                kind: AgentSessionReferenceKind::Path,
                value: "/tmp/explicit-rollout.jsonl".to_owned(),
            }),
        )
        .await;

        assert_eq!(
            provider.published_targets.codex_panes().count(),
            0,
            "any explicit agent-session reference must suppress the sessionless heuristic"
        );
        g7_service_binding(&mut harness, &mut provider, queued).await;
        let snapshot = harness.shared.borrow();
        assert_eq!(
            snapshot.task_run(&target.run_id).map(|run| &run.key),
            Some(&provisional_key),
            "the explicit path event must not heuristically promote the pane run"
        );
        assert!(snapshot.task_run_bindings().all(|(key, owner)| {
            *owner != target.run_id
                || !matches!(
                    key,
                    RunKey::Native {
                        provider: Provider::Codex,
                        ..
                    }
                )
        }));
        assert!(
            snapshot
                .task_run_by_key(&RunKey::Native {
                    provider: Provider::Codex,
                    sid: stale_sid.to_owned(),
                })
                .is_none(),
            "a binding queued before the explicit path must not gain a durable owner"
        );
        drop(snapshot);

        drop(provider_sender);
        provider_thread.stop().await.unwrap();
        harness.shutdown().await;
    }

    #[tokio::test]
    async fn g7_round2_queued_binding_drops_after_provider_transition() {
        let mut harness = LaneModelHarness::new();
        let (provider_sender, mut provider, provider_thread) = g7_provider_integration();
        let stale_sid = "66666666-6666-4666-8666-666666666666";

        g7_install_pane_snapshot(
            &mut harness,
            &mut provider,
            "codex",
            PaneAgentStatus::Working,
            None,
        )
        .await;
        let target = provider
            .published_targets
            .codex_panes()
            .next()
            .expect("sessionless Codex pane must publish a target");
        let provisional_key = harness
            .shared
            .borrow()
            .task_run(&target.run_id)
            .expect("published pane target must own a task run")
            .key
            .clone();
        let queued = CodexPaneBinding {
            run_id: target.run_id,
            sid: stale_sid.to_owned(),
            observed_at_ms: target.detected_at_ms,
        };

        g7_install_pane_snapshot(
            &mut harness,
            &mut provider,
            "claude",
            PaneAgentStatus::Working,
            None,
        )
        .await;
        assert_eq!(provider.published_targets.codex_panes().count(), 0);
        g7_service_binding(&mut harness, &mut provider, queued).await;

        let snapshot = harness.shared.borrow();
        assert_eq!(
            snapshot.task_run(&target.run_id).map(|run| &run.key),
            Some(&provisional_key),
            "a queued Codex binding must not survive a real provider transition"
        );
        assert!(
            snapshot
                .task_run_by_key(&RunKey::Native {
                    provider: Provider::Codex,
                    sid: stale_sid.to_owned(),
                })
                .is_none(),
            "the stale queued SID must not gain a durable owner"
        );
        drop(snapshot);

        drop(provider_sender);
        provider_thread.stop().await.unwrap();
        harness.shutdown().await;
    }

    #[tokio::test]
    async fn g7_round3_same_or_older_redetection_cannot_reuse_episode_timestamp() {
        let first_detection_ms = G7_DETECTION_MS;
        let run = g7_provisional(
            "same-millisecond-redetection",
            1,
            first_detection_ms - 10_000,
        );
        let mut harness = LaneModelHarness::with_model(g7_model(std::slice::from_ref(&run)));
        let (provider_sender, mut provider, provider_thread) = g7_provider_integration();
        let stale_sid = "77777777-7777-4777-8777-777777777777";
        let current_sid = "88888888-8888-4888-8888-888888888888";

        provider.observe_sessionless_codex_events(
            &[g7_execution_observation(
                &run,
                Provider::Codex,
                None,
                first_detection_ms,
            )],
            true,
        );
        provider.publish_targets(&harness.shared);
        let episode_a = provider
            .published_targets
            .codex_panes()
            .next()
            .expect("episode A must publish");
        assert_eq!(episode_a.detected_at_ms, first_detection_ms);
        let queued = CodexPaneBinding {
            run_id: episode_a.run_id,
            sid: stale_sid.to_owned(),
            observed_at_ms: episode_a.detected_at_ms,
        };

        provider.observe_sessionless_codex_events(
            &[g7_execution_observation(
                &run,
                Provider::Claude,
                None,
                first_detection_ms,
            )],
            false,
        );
        provider.publish_targets(&harness.shared);
        assert_eq!(provider.published_targets.codex_panes().count(), 0);

        for redetection_ms in [first_detection_ms, first_detection_ms - 1] {
            provider.observe_sessionless_codex_events(
                &[g7_execution_observation(
                    &run,
                    Provider::Codex,
                    None,
                    redetection_ms,
                )],
                true,
            );
            provider.publish_targets(&harness.shared);
            assert_eq!(
                provider.published_targets.codex_panes().count(),
                0,
                "same-millisecond or regressed time must not reactivate eligibility"
            );
        }

        g7_service_binding(&mut harness, &mut provider, queued).await;
        assert_eq!(
            harness
                .shared
                .borrow()
                .task_run(&episode_a.run_id)
                .map(|run| &run.key),
            Some(&run.1),
            "episode A's queued binding must remain stale after rejected re-entry"
        );

        let later_detection_ms = first_detection_ms + 1;
        provider.observe_sessionless_codex_events(
            &[g7_execution_observation(
                &run,
                Provider::Codex,
                None,
                later_detection_ms,
            )],
            true,
        );
        provider.publish_targets(&harness.shared);
        let episode_b = provider
            .published_targets
            .codex_panes()
            .next()
            .expect("strictly later episode B must publish");
        assert_eq!(episode_b.run_id, episode_a.run_id);
        assert_eq!(episode_b.detected_at_ms, later_detection_ms);

        g7_service_binding(
            &mut harness,
            &mut provider,
            CodexPaneBinding {
                run_id: episode_b.run_id,
                sid: current_sid.to_owned(),
                observed_at_ms: episode_b.detected_at_ms,
            },
        )
        .await;

        let snapshot = harness.shared.borrow();
        assert_eq!(
            snapshot.task_run(&episode_b.run_id).map(|run| &run.key),
            Some(&RunKey::Native {
                provider: Provider::Codex,
                sid: current_sid.to_owned(),
            }),
            "the current episode binding must retain the normal one-shot promotion path"
        );
        assert!(
            snapshot
                .task_run_by_key(&RunKey::Native {
                    provider: Provider::Codex,
                    sid: stale_sid.to_owned(),
                })
                .is_none(),
            "episode A must never acquire a durable binding"
        );
        drop(snapshot);
        provider.publish_targets(&harness.shared);
        assert!(
            !provider
                .sessionless_codex_detection_history
                .contains_key(&episode_b.run_id),
            "episode history must be released after the run is no longer live provisional"
        );

        drop(provider_sender);
        provider_thread.stop().await.unwrap();
        harness.shutdown().await;
    }

    #[tokio::test]
    async fn g7_round3_queued_binding_drops_after_snapshot_absence() {
        let run = g7_provisional("snapshot-absence", 1, G7_DETECTION_MS - 10_000);
        let mut harness = LaneModelHarness::with_model(g7_model(std::slice::from_ref(&run)));
        let (provider_sender, mut provider, provider_thread) = g7_provider_integration();
        let stale_sid = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa";

        provider.observe_sessionless_codex_terminals(
            &harness.shared,
            &HashSet::from([run.3.terminal_id.clone()]),
        );
        provider.publish_targets(&harness.shared);
        let target = provider
            .published_targets
            .codex_panes()
            .next()
            .expect("snapshot-present Codex pane must publish a target");
        let queued = CodexPaneBinding {
            run_id: target.run_id,
            sid: stale_sid.to_owned(),
            observed_at_ms: target.detected_at_ms,
        };

        provider.observe_sessionless_codex_terminals(&harness.shared, &HashSet::new());
        provider.publish_targets(&harness.shared);
        assert_eq!(
            provider.published_targets.codex_panes().count(),
            0,
            "snapshot absence must remove active detection eligibility"
        );
        g7_service_binding(&mut harness, &mut provider, queued).await;

        let snapshot = harness.shared.borrow();
        assert_eq!(
            snapshot.task_run(&target.run_id).map(|run| &run.key),
            Some(&run.1),
            "a binding queued before snapshot absence must not promote the provisional run"
        );
        assert!(
            snapshot
                .task_run_by_key(&RunKey::Native {
                    provider: Provider::Codex,
                    sid: stale_sid.to_owned(),
                })
                .is_none(),
            "the stale snapshot-era SID must not gain a durable owner"
        );
        drop(snapshot);

        drop(provider_sender);
        provider_thread.stop().await.unwrap();
        harness.shutdown().await;
    }

    #[tokio::test]
    async fn g7_round2_queued_binding_drops_after_terminal_event() {
        let mut harness = LaneModelHarness::new();
        let (provider_sender, mut provider, provider_thread) = g7_provider_integration();
        let stale_sid = "99999999-9999-4999-8999-999999999999";

        g7_install_pane_snapshot(
            &mut harness,
            &mut provider,
            "codex",
            PaneAgentStatus::Working,
            None,
        )
        .await;
        let target = provider
            .published_targets
            .codex_panes()
            .next()
            .expect("sessionless Codex pane must publish a target");
        let provisional_key = harness
            .shared
            .borrow()
            .task_run(&target.run_id)
            .expect("published pane target must own a task run")
            .key
            .clone();
        let queued = CodexPaneBinding {
            run_id: target.run_id,
            sid: stale_sid.to_owned(),
            observed_at_ms: target.detected_at_ms,
        };

        let execution_id = harness
            .shared
            .borrow()
            .executions()
            .find(|execution| {
                execution.task_run_id == target.run_id && !execution.state.is_terminal()
            })
            .unwrap()
            .execution_id
            .clone();
        let ApplyOutcome::Applied(persist) = harness
            .reducer
            .apply(NormalizedEvent::ExecutionEnd {
                metadata: metadata("session", "pane_exited"),
                execution_id,
            })
            .unwrap()
        else {
            panic!("terminal event should apply");
        };
        let _ = persist_submission(&mut harness.persistence, &mut harness.reducer, persist)
            .await
            .unwrap();
        provider.publish_targets(&harness.shared);
        assert_eq!(provider.published_targets.codex_panes().count(), 0);
        assert!(
            harness
                .shared
                .borrow()
                .executions()
                .filter(|execution| execution.task_run_id == target.run_id)
                .all(|execution| execution.state.is_terminal())
        );
        g7_service_binding(&mut harness, &mut provider, queued).await;

        let snapshot = harness.shared.borrow();
        assert_eq!(
            snapshot.task_run(&target.run_id).map(|run| &run.key),
            Some(&provisional_key),
            "a queued binding must not promote a terminal pane run"
        );
        assert!(
            snapshot
                .task_run_by_key(&RunKey::Native {
                    provider: Provider::Codex,
                    sid: stale_sid.to_owned(),
                })
                .is_none()
        );
        drop(snapshot);

        drop(provider_sender);
        provider_thread.stop().await.unwrap();
        harness.shutdown().await;
    }

    #[tokio::test]
    async fn reused_provisional_anchors_rollout_window_at_actual_codex_detection() {
        let directory = tempfile::tempdir().unwrap();
        let root = directory.path().join("home/.codex/sessions");
        let provisional_start_ms = G7_DETECTION_MS;
        let detected_at_ms = G7_DETECTION_MS + 10_000;
        let _ = g7_rollout(&root, provisional_start_ms + 500, "before-detection");
        let run = g7_provisional("reused-provisional", 1, provisional_start_ms);
        let (_model_sender, shared) =
            watch::channel(Arc::new(g7_model(std::slice::from_ref(&run))));
        let (provider_sender, mut provider, provider_thread) = g7_provider_integration();

        provider.observe_sessionless_codex_events(
            &[g7_execution_observation(
                &run,
                Provider::Codex,
                None,
                detected_at_ms,
            )],
            true,
        );
        provider.publish_targets(&shared);
        let targets = provider.published_targets.clone();
        let (mut worker, mut pending) = g7_worker(&root);

        process_adapter_worker(&mut worker, &targets, &mut pending);
        assert!(
            g7_bindings(&drain_pending(&mut pending)).is_empty(),
            "a rollout created after provisional start but before actual Codex detection must not bind"
        );

        let (_, same_second_sid) = g7_rollout(&root, detected_at_ms - 500, "same-detection-second");
        process_adapter_worker(&mut worker, &targets, &mut pending);
        assert_eq!(
            g7_bindings(&drain_pending(&mut pending)),
            vec![(run.0, same_second_sid)],
            "a rollout created in the actual detection second must remain eligible"
        );

        drop(provider_sender);
        provider_thread.stop().await.unwrap();
    }

